class DistanceQueue {
    static final class State {
        final int node;
        final long distance;

        State(int node, long distance) {
            this.node = node;
            this.distance = distance;
        }
    }

    static PriorityQueue<State> newQueue() {
        return new PriorityQueue<>(
            (a, b) -> Long.compare(a.distance, b.distance)
        );
    }
}

